  [67581] = "guide_describe[49]消耗<color=#FE8B15>行动许可</color>，可以挑战<color=#FE8B15>燃烧冲程</color>关卡，挑战成功即可获得<color=#FE8B15>战略点</color>和<color=#FE8B15>熵核残片</color>。",
