  [124130] = "attribute[18]技能生命偷取",
  [124171] = "event[1386]黑泽八云监督逝世两周年之际，黑泽工作室的惊悚片新作《如月的幽灵列车》正式上映，引发热议。\n电影评论家：“黑泽工作室用这部新作消除了外界对其未来前景的怀疑。在大体继承了黑泽八云监督的惊悚风格的基础上，也带来了全新的视觉升级。”",
  [124172] = "hero_data[1088]M・A・O",
