  [191932] = "item[1262]积淀凝块",
  [191933] = "battle_buff[1607]card_032我方增伤",
  [191975] = "item[304607]红尘快意——在这尚武为尊的江湖，人形们大显身手，嬉笑恩仇，展现着传统武艺与现代解构的极致碰撞。\n人迹罕至的清潭边，持剑而立的身影，正品味着山间清风带来的快慰之意，邀人江湖与共。\n“长剑、斗笠、数两碎银，出行必要之物都已打点齐备了。山河广阔，教授可有闲情与我同游？”\n<color=#969696>[心智投影 黛烟]</color>",
