  [197771] = "portrait[428001]里程·心智",
  [197781] = "noun_des[4]环球万事服务的前身可以追溯到三战之前，是一家给上流人士提供会员制的高级定制服务的公司。由于市场下滑，而平民人形市场开始萌芽，环球万事服务转型开始研发普通民用人形，此后在全球民用人形市场内迅速占据了巨大的份额。其业务涵盖了人们生活的方方面面，继而发展成为全球最大的民用人形生产商。",
  [197792] = "item[23118]算量穿透",
  [197823] = "event_choice[26216]龙牙风风拳！（花费10%血量，有20%概率获得一个随机重载协议。）",
