  [260718] = "tip_language[8004]性能占用高",
  [260750] = "tip_language[4002]未选择算法",
  [260774] = "sector_stage[330122129]零落祷词",
  [260782] = "story_avg[3305213]寂静与黑暗会吞噬万物，无声真空将代替一切。",
  [260789] = "tip_language[24008]「启牌见礼」活动规则",
  [260793] = "event[1663]购入弥灵后没过多久，弥灵就作为二手人形再次出现在了交易市场上。\n收购弥灵的家庭将她低价出售给了一个动物园，而根据弥灵被购入和转手时登记的雇主信息来看，那位购买弥灵的老妇人很有可能已经不在人世了。\n弥灵被转卖后的工作地点，是一家以仿生机械动物为主业的公司所投资创办的主题动物园。\n根据动物园的工作分派，她需要在其中兼任管理员、引导员和饲养员，并重点负责成年人难以完成的，引导幼年游客和狭小区域基础检修工作。",
  [260821] = "tip_language[8721]替换失败，队伍中不能存在濒死状态的人形",
  [260854] = "guide_step[601020120]结果还是想拿我当挡箭牌吗！",
